            {/* Output Ports */}
            {outputPorts.length > 0 && (
                <div>
                    <h3 className="custom-card-title">
                        Output Ports
                    </h3>
                    <div className="custom-table-container" style={{ overflowX: 'auto' }}>
                        <table className="custom-table">
                            <thead>
