const BASE_URL = import.meta.env.BASE_URL;

const normalizePath = (path) => {
    if (!path) return path;

    // If it's the absolute localhost backend, normalize it to the proxy path
    // ONLY in development mode where the Vite proxy is active.
    if (import.meta.env.DEV && path.startsWith('http://localhost:8000/dmesh')) {
        const relativePath = path.replace('http://localhost:8000/', '');
        return `${BASE_URL}${relativePath}`;
    }

    if (path.startsWith('http')) return path;

    // If it already starts with BASE_URL, don't normalize again
    if (path.startsWith(BASE_URL)) return path;

    // Prefix relative paths starting with / with BASE_URL
    if (path.startsWith('/')) {
        return `${BASE_URL}${path.slice(1)}`;
    }
    return path;
};

export default Flow;

function Flow({ isExpanded = false }) {
    // Router Hooks
    const location = useLocation();
    const navigate = useNavigate();

    // Theme Context
    const { mode } = useThemeContext();

    // Data Mesh Operations State - URL will be loaded from config.json
    const [dataMeshOperationsUrl, setDataMeshOperationsUrl] = React.useState('');

    const [dataMeshOperations, setDataMeshOperationalData] = React.useState([]);
    const [dataMeshOperationsRaw, setDataMeshOperationalDataRaw] = React.useState('');
    const [isLoading, setIsLoading] = React.useState(true);
    const [error, setError] = React.useState(null);
    const [config, setConfig] = React.useState<any>({ iconMap: {}, tiers: {}, domainPalette: [], defaultDataMeshOperationalDataUrl: '', dataMeshOperationsList: [], 'single-domain-default-filter': false, 'zoom-to-fit-columns': true }); // Config state
    const [configError, setConfigError] = React.useState(null); // Track config loading errors
    const [showDataMeshOperationsModal, setShowDataMeshOperationsModal] = React.useState(false);

    const [allEnvsData, setAllEnvsData] = React.useState([]);
    const [selectedEnv, setSelectedEnv] = React.useState(() => {
        return localStorage.getItem('dmesh-selected-env') || '';
    });

    React.useEffect(() => {
        if (selectedEnv) {
            localStorage.setItem('dmesh-selected-env', selectedEnv);
        }
    }, [selectedEnv]);

    React.useEffect(() => {
        if (config?.['multi-environment'] && Array.isArray(config['multi-environment']) && allEnvsData.length > 0) {
            const defaultEnv = config['default-environment'] || config['multi-environment'][config['multi-environment'].length - 1];
            const currentEnv = selectedEnv || defaultEnv;
            if (!selectedEnv) {
                setSelectedEnv(currentEnv);
            }
            const envObj = allEnvsData.find(e => String(e.env).toLowerCase() === String(currentEnv).toLowerCase());
            setDataMeshOperationalData(envObj ? (envObj.data || []) : []);
        }
    }, [selectedEnv, allEnvsData, config]);

    // Load Config
    React.useEffect(() => {
        Promise.all([
            fetch(normalizePath(`/config/base/config.yaml?t=${Date.now()}`))
                .then(res => {
                    if (!res.ok) {
                        throw new Error(`Failed to load config.yaml (${res.status} ${res.statusText}). Make sure the file exists in the public directory.`);
                    }
                    return res.text();
                }),
            fetch(normalizePath(`/config/custom/config.yaml?t=${Date.now()}`))
                .then(res => res.ok ? res.text() : null)
                .catch(() => null)
        ])
            .then(([configText, customConfigText]) => {
                if (!configText || configText.trim() === '') {
                    throw new Error('config.yaml is empty. Please add configuration settings to the file.');
                }

                let data;
                try {
                    data = YAML.parse(configText);
                } catch (yamlErr) {
                    throw new Error(`config.yaml contains invalid YAML syntax: ${yamlErr.message}. Please check the file format.`);
                }

                if (!data || typeof data !== 'object') {
                    throw new Error('config.yaml must contain a valid YAML document with configuration settings.');
                }

                if (customConfigText && customConfigText.trim() !== '') {
                    try {
                        const customData = YAML.parse(customConfigText);
                        if (customData && typeof customData === 'object') {
                            Object.keys(customData).forEach(key => {
                                if (customData[key] !== null && typeof customData[key] === 'object' && !Array.isArray(customData[key]) &&
                                    data[key] !== null && typeof data[key] === 'object' && !Array.isArray(data[key])) {
                                    data[key] = { ...data[key], ...customData[key] };
                                } else {
                                    data[key] = customData[key];
                                }
                            });
                        }
                    } catch (yamlErr) {
                        console.warn(`customConfig.yaml contains invalid YAML syntax: ${yamlErr.message}. Ignoring custom config.`);
                    }
                }

                // Validate required fields
                if (!data.defaultDataMeshOperationalDataUrl) {
                    setConfigError('config.yaml is missing required field "defaultDataMeshOperationalDataUrl". Please add this field with the path to your data mesh operations YAML file.');
                    return;
                }

                const loadedConfig = {
                    ...data,
                    iconMap: data.iconMap || {},
                    tiers: data.tiers || {},
                    observability: data.observability || {},
                    defaultDataMeshOperationalDataUrl: normalizePath(data.defaultDataMeshOperationalDataUrl),
                    dataMeshOperationsList: (data.sampleDataMeshOperationalDataUrls || []).map(reg => ({
                        original: reg,
                        normalized: normalizePath(reg)
                    }))
                };
                setConfig(loadedConfig);
                setConfigError(null);

                // Set initial dataMeshOperations URL from config
                setDataMeshOperationsUrl(loadedConfig.defaultDataMeshOperationalDataUrl);
            })
            .catch(err => {
                console.error("Failed to load config.yaml", err);
                setConfigError(err.message);
            });
    }, []);

    // React Flow State
    const [nodes, setNodes, onNodesChange] = useNodesState([]);
    const [edges, setEdges, onEdgesChange] = useEdgesState([]);
    const [selection, setSelection] = React.useState<any>({ id: null, kind: null });

    // Sync URL -> Selection
    React.useEffect(() => {
        if (!dataMeshOperations || dataMeshOperations.length === 0) return;

        const parts = location.pathname.split('/').filter(Boolean); // e.g. ['env', 'Prod', 'mesh', 'domain', 'food_production', 'dataproduct', '1234']
        if (parts[0] !== 'env' || parts[2] !== 'mesh') return;

        const urlEnv = parts[1];
        if (selectedEnv !== urlEnv) {
            setSelectedEnv(urlEnv);
        }

        if (parts.length >= 7 && parts[3] === 'domain' && parts[5] === 'dataproduct') {
            const dataproductId = parts[6];
            const isContracts = parts[7] === 'contracts';

            if (isContracts) {
                // User wants the contracts for this data product. 
                // We find the product, get its first output port, and select that contract.
                const product = dataMeshOperations.find(n => String(n.id) === dataproductId && n.kind === 'DataProduct');
                if (product && product.outputPorts && product.outputPorts.length > 0) {
                    const contractId = product.outputPorts[0].contractId;
                    if (selection.id !== contractId) {
                        setSelection({ id: contractId, kind: 'DataContract' });
                    }
                }
            } else {
                if (selection.id !== dataproductId) {
                    setSelection({ id: dataproductId, kind: 'DataProduct' });
                }
            }
        } else {
            // Root mesh path
            if (selection.id !== null) {
                setSelection({ id: null, kind: null });
            }
        }
    }, [location.pathname, dataMeshOperations]);

    // Sync Selection -> URL
    const isFirstRun = React.useRef(true);
    React.useEffect(() => {
        if (!dataMeshOperations || dataMeshOperations.length === 0) return;

        if (isFirstRun.current) {
            isFirstRun.current = false;
            return;
        }

        if (selection.id) {
            if (selection.kind === 'DataProduct') {
                const item = dataMeshOperations.find(d => String(d.id) === String(selection.id));
                if (item) {
                    const expectedPath = `/env/${selectedEnv}/mesh/domain/${item.domain}/dataproduct/${item.id}`;
                    if (location.pathname !== expectedPath) {
                        navigate(expectedPath, { replace: true });
                    }
                } else {
                    navigate(`/env/${selectedEnv}/mesh`, { replace: true });
                }
            } else if (selection.kind === 'DataContract') {
                const producerNode = dataMeshOperations.find(n => n.kind === 'DataProduct' && n.outputPorts?.some(p => String(p.contractId) === String(selection.id)));
                if (producerNode) {
                    const expectedPath = `/env/${selectedEnv}/mesh/domain/${producerNode.domain}/dataproduct/${producerNode.id}/contracts`;
                    if (location.pathname !== expectedPath) {
                        navigate(expectedPath, { replace: true });
                    }
                } else {
                    navigate(`/env/${selectedEnv}/mesh`, { replace: true });
                }
            }
        } else {
            const parts = location.pathname.split('/').filter(Boolean);
            if (parts.length !== 3 || parts[0] !== 'env' || parts[2] !== 'mesh' || parts[1] !== selectedEnv) {
                navigate(`/env/${selectedEnv}/mesh`, { replace: true });
            }
        }
    }, [selection, dataMeshOperations, selectedEnv]);


    // Dispatch breadcrumbs based on selection
    React.useEffect(() => {
        const getProductAlias = (itemObj) => {
            const tier = resolveOdpsPath({ raw: itemObj }, '_customProperty("dataProductTier")');
            const aliasMap = config?.dataMeshBreadcrumbDataProductAliasMap || {};
            if (tier && aliasMap[tier]) return aliasMap[tier];
            return aliasMap["*"] || "Data Product";
        };

        if (selection.id) {
            const item = dataMeshOperations.find(d => String(d.id) === String(selection.id));
            if (item) {
                if (selection.kind === 'DataProduct') {
                    const domainAlias = config?.domainNameCustomisation?.[item.domain] || item.domain;
                    const name = resolveOdpsPath({ raw: item }, '_customProperty("dataProductBusinessName")') || item?.name || selection.id;
                    const finalName = domainAlias ? `(${domainAlias}) ${name}` : name;
                    const typeAlias = getProductAlias(item);
                    window.dispatchEvent(new CustomEvent('set-breadcrumbs', { detail: [typeAlias, finalName] }));
                } else if (selection.kind === 'DataContract') {
                    const producerNode = dataMeshOperations.find(n => n.kind === 'DataProduct' && n.outputPorts?.some(p => String(p.contractId) === String(selection.id)));
                    if (producerNode) {
                        const domainAlias = config?.domainNameCustomisation?.[producerNode.domain] || producerNode.domain;
                        const name = resolveOdpsPath({ raw: producerNode }, '_customProperty("dataProductBusinessName")') || producerNode?.name || producerNode.id;
                        const finalName = domainAlias ? `(${domainAlias}) ${name}` : name;
                        const typeAlias = getProductAlias(producerNode);
                        window.dispatchEvent(new CustomEvent('set-breadcrumbs', { detail: [typeAlias, finalName, 'Data Contracts'] }));
                    } else {
